questionvariables.text:
tsets: [[5], [5, 11], [5, 11, 17], [5, 11, 17, 23], [5, 11, 17, 23, 29],
        [5, 11, 17, 23, 29, 41, 47, 53, 59, 71, 83, 89]];
tsetstxt: ["just 5", "5 and 11", "5, 11 and 17", "5, 11, 17 and 23", "5, 11, 17, 23 and 29", "the twelve primes of the form \\(6k + 5\\) below 100"];
tprods: map(lambda([s], apply("*", s)), tsets);
ta1: 6*P - 1;
ta2: [[w_form, false, "\\(6P + 5\\) does not leave remainder 5 on division by 6."],
      [w_five, true, "\\(6P + 5\\) is divisible by 5, one of the primes \\(p_1, \\ldots, p_n\\), so its prime factor of the form \\(6k + 5\\) could be one already in the list."],
      [w_prime, false, "\\(6P + 5\\) might be prime, and the proof needs \\(M\\) to be a product of several primes."],
      [w_big, false, "\\(6P + 5\\) is larger than every prime of the form \\(6k + 5\\), so it cannot have such a prime factor."]];
validate_mp(ex) := block([e], e: ev(expand(ex), simp), if not(member(P, listofvars(ex))) then "Write M in terms of P." else if not(every(lambda([v], is(v = P)), listofvars(ex))) then "Use only the letter P." else if not(ev(polynomialp(e, [P], ratnump), simp)) then "Write M using only whole numbers and powers of P, combined with +, -, * and /." else if is(ev(hipow(e, P), simp) > 20) then "Use a power of P no higher than 20." else "");

feedbackvariables.text:
idx: makelist(i, i, 1, length(tsets));
mvals: map(lambda([pp], ev(subst(P = pp, ans1), simp)), tprods);
szbad: sublist(idx, lambda([i], not(integerp(mvals[i]) and (is(i < 4) or is(mvals[i] > 1)))));
sizeok: is(szbad = []);
szi: if sizeok then 1 else first(szbad);
rsbad: if sizeok then sublist(idx, lambda([i], is(mod(mvals[i], 6) # 5))) else [];
resok: sizeok and is(rsbad = []);
rsi: if rsbad = [] then 1 else first(rsbad);
cpbad: if resok then sublist(idx, lambda([i], not(every(lambda([pr], is(mod(mvals[i], pr) # 0)), tsets[i])))) else [];
rs0: ev(ratsimp(ans1), simp);
dd0: ev(denom(rs0), simp);
c0: ev(subst(P = 0, num(rs0)), simp);
bigp: if resok and is(cpbad = []) and integerp(c0) and integerp(dd0) and is(c0 # 0) and is(abs(c0) < 10^15) then sublist(map(first, ifactors(abs(c0))), lambda([pr], is(mod(pr, 6) = 5) and is(mod(dd0, pr) # 0))) else [];
bigp1: if bigp = [] then 5 else first(bigp);
allok: resok and is(cpbad = []) and is(bigp = []);
badi: if cpbad = [] then 1 else first(cpbad);
badp: if cpbad = [] then 5 else first(sublist(tsets[badi], lambda([pr], is(mod(mvals[badi], pr) = 0))));
